@tailwind base;
@tailwind components;
@tailwind utilities;

/**
 * Design tokens.
 *
 * This file is the reason a pasted block looks right. Every block and page
 * styles itself with semantic classes — `bg-card`, `text-muted-foreground`,
 * `border-border` — rather than literal colours, so they inherit whatever
 * you define here instead of fighting it. Change a value below and every
 * section in the project moves with it.
 *
 * Values are bare HSL channels, not `hsl(...)` calls. That is what lets
 * Tailwind compose them with an alpha suffix: `bg-primary/10` expands to
 * `hsl(var(--primary) / 0.1)`, which is impossible if the variable already
 * carries its own function wrapper.
 */

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 240 10% 4%;

    --card: 0 0% 100%;
    --card-foreground: 240 10% 4%;

    --popover: 0 0% 100%;
    --popover-foreground: 240 10% 4%;

    --primary: 243 75% 59%;
    --primary-foreground: 0 0% 100%;

    --secondary: 240 5% 96%;
    --secondary-foreground: 240 6% 10%;

    --muted: 240 5% 96%;
    --muted-foreground: 240 4% 46%;

    --accent: 240 5% 96%;
    --accent-foreground: 240 6% 10%;

    --destructive: 0 72% 51%;
    --destructive-foreground: 0 0% 100%;

    --border: 240 6% 90%;
    --input: 240 6% 90%;
    --ring: 243 75% 59%;

    --radius: 0.75rem;
  }

  .dark {
    --background: 240 10% 4%;
    --foreground: 0 0% 98%;

    --card: 240 8% 6%;
    --card-foreground: 0 0% 98%;

    --popover: 240 8% 6%;
    --popover-foreground: 0 0% 98%;

    /* Lifted and desaturated against the dark ground — the light-mode
       primary is too dark here to read as an accent. */
    --primary: 234 89% 74%;
    --primary-foreground: 240 10% 4%;

    --secondary: 240 4% 14%;
    --secondary-foreground: 0 0% 98%;

    --muted: 240 4% 14%;
    --muted-foreground: 240 5% 65%;

    --accent: 240 4% 14%;
    --accent-foreground: 0 0% 98%;

    --destructive: 0 63% 55%;
    --destructive-foreground: 0 0% 98%;

    --border: 240 4% 18%;
    --input: 240 4% 18%;
    --ring: 234 89% 74%;
  }
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground antialiased;
  }

  /**
   * Global motion opt-out.
   *
   * Blocks guard their own animations with Tailwind's `motion-safe:`, but
   * third-party CSS and anything you add later will not. This is the
   * backstop: it neutralises every animation and transition on the page
   * for users who have asked the OS for reduced motion, rather than
   * relying on each author to remember.
   */
  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }
}

import type { Metadata } from 'next'
import { ThemeProvider } from '@/components/theme-provider'
import './globals.css'

/**
 * Root layout.
 *
 * `suppressHydrationWarning` on <html> is required, not cosmetic: the theme
 * script below writes a class onto that element before React hydrates, so
 * the server markup and the first client render disagree by design. Without
 * the attribute, React logs a hydration mismatch on every single page load.
 */

export const metadata: Metadata = {
  title: {
    default: 'Acme — Ship the interface you sketched',
    template: '%s — Acme',
  },
  description:
    'Every section of a real product, ready to paste. No component library to adopt, no runtime to ship.',
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        {/*
          Applies the stored theme before first paint.

          This has to be a blocking inline script in <head>. Anything that
          runs after hydration — an effect, a provider's mount — happens at
          least one frame too late, and the user sees a white flash before
          the dark theme lands. That flash is the single most-reported bug
          in every hand-rolled dark mode.
        */}
        <script
          dangerouslySetInnerHTML={{
            __html: `
              try {
                var stored = localStorage.getItem('theme')
                var dark = stored
                  ? stored === 'dark'
                  : window.matchMedia('(prefers-color-scheme: dark)').matches
                if (dark) document.documentElement.classList.add('dark')
              } catch (e) {}
            `,
          }}
        />
      </head>
      <body>
        <ThemeProvider>{children}</ThemeProvider>
      </body>
    </html>
  )
}

'use client'

/**
 * Minimal theme provider — light/dark, persisted, no dependency.
 *
 * Deliberately not `next-themes`. That library is excellent and about 5 KB,
 * but a starter should not spend its first dependency on something this
 * file does in forty lines. Swap it in later if you need system-preference
 * tracking, forced themes per route, or more than two themes.
 *
 * The initial class is applied by the inline script in `app/layout.tsx`,
 * before first paint. This provider only handles *changes* — reading state
 * here on mount and applying it would reintroduce the flash the script
 * exists to prevent.
 */

import * as React from 'react'

type Theme = 'light' | 'dark'

interface ThemeContextValue {
  theme: Theme
  setTheme: (theme: Theme) => void
  toggle: () => void
}

const ThemeContext = React.createContext<ThemeContextValue | null>(null)

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  // Seeded from the DOM, which the layout script has already set — not from
  // localStorage, so the provider agrees with what is on screen.
  const [theme, setThemeState] = React.useState<Theme>(() => {
    if (typeof document === 'undefined') return 'light'
    return document.documentElement.classList.contains('dark') ? 'dark' : 'light'
  })

  const setTheme = React.useCallback((next: Theme) => {
    setThemeState(next)
    document.documentElement.classList.toggle('dark', next === 'dark')
    try {
      localStorage.setItem('theme', next)
    } catch {
      // Private mode, or storage disabled. The theme still applies for
      // this session; it just will not survive a reload.
    }
  }, [])

  const value = React.useMemo(
    () => ({
      theme,
      setTheme,
      toggle: () => setTheme(theme === 'dark' ? 'light' : 'dark'),
    }),
    [theme, setTheme],
  )

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
}

/** Read and change the theme. Throws outside a ThemeProvider. */
export function useTheme(): ThemeContextValue {
  const context = React.useContext(ThemeContext)
  if (!context) throw new Error('useTheme must be used inside a ThemeProvider')
  return context
}

/**
 * PostCSS configuration.
 *
 * Tailwind runs as a PostCSS plugin, so without this file the `@tailwind`
 * directives in `app/globals.css` are passed through to the browser as
 * literal text and nothing is styled at all. It is three lines and it is
 * not optional.
 */
export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

import type { Config } from 'tailwindcss'

/**
 * Tailwind configuration.
 *
 * The `colors` block is what maps `bg-card` and `text-muted-foreground` onto
 * the CSS variables in `app/globals.css`. Without it those class names do
 * not exist and every block renders unstyled — this file and that one are a
 * pair, and copying one without the other is the most common way to end up
 * with a "the block looks broken" bug report.
 *
 * `<alpha-value>` is the placeholder Tailwind substitutes when you write an
 * opacity suffix, so `bg-primary/10` works on a variable-driven colour.
 */
const config: Config = {
  darkMode: 'class',
  content: ['./app/**/*.{ts,tsx}', './components/**/*.{ts,tsx}'],
  theme: {
    extend: {
      colors: {
        background: 'hsl(var(--background) / <alpha-value>)',
        foreground: 'hsl(var(--foreground) / <alpha-value>)',
        card: {
          DEFAULT: 'hsl(var(--card) / <alpha-value>)',
          foreground: 'hsl(var(--card-foreground) / <alpha-value>)',
        },
        popover: {
          DEFAULT: 'hsl(var(--popover) / <alpha-value>)',
          foreground: 'hsl(var(--popover-foreground) / <alpha-value>)',
        },
        primary: {
          DEFAULT: 'hsl(var(--primary) / <alpha-value>)',
          foreground: 'hsl(var(--primary-foreground) / <alpha-value>)',
        },
        secondary: {
          DEFAULT: 'hsl(var(--secondary) / <alpha-value>)',
          foreground: 'hsl(var(--secondary-foreground) / <alpha-value>)',
        },
        muted: {
          DEFAULT: 'hsl(var(--muted) / <alpha-value>)',
          foreground: 'hsl(var(--muted-foreground) / <alpha-value>)',
        },
        accent: {
          DEFAULT: 'hsl(var(--accent) / <alpha-value>)',
          foreground: 'hsl(var(--accent-foreground) / <alpha-value>)',
        },
        destructive: {
          DEFAULT: 'hsl(var(--destructive) / <alpha-value>)',
          foreground: 'hsl(var(--destructive-foreground) / <alpha-value>)',
        },
        border: 'hsl(var(--border) / <alpha-value>)',
        input: 'hsl(var(--input) / <alpha-value>)',
        ring: 'hsl(var(--ring) / <alpha-value>)',
      },
      borderRadius: {
        lg: 'var(--radius)',
        md: 'calc(var(--radius) - 2px)',
        sm: 'calc(var(--radius) - 4px)',
      },
    },
  },
  plugins: [],
}

export default config

